1	package review
2	
3	import (
4		"encoding/json"
5		"regexp"
6		"strconv"
7		"strings"
8	
9		reviewtypes "github.com/entireio/cli/cmd/entire/cli/review/types"
10	)
11	
12	// trailFindingsJSONInstructions is the trail-mode output contract. Reviewers
13	// and the judge end with this JSON line so posting reads their findings
14	// structurally instead of interpreting prose. The example line must parse
15	// with splitTrailJSON; a test enforces that.
16	const trailFindingsJSONInstructions = `Final line (required, read by a program):
17	End your output with exactly one line holding only this JSON object, with no code fence and nothing after it:
18	{"summary":"one-sentence verdict","comments":[{"severity":"high","body":"bug; impact; fix","location":{"granularity":"line","file_path":"path/to/file.go","start_line":42}}]}
19	- Add one comment per actionable finding reported above, with the same severity: high, medium, or low.
20	- location.granularity is line (with start_line), range (with start_line and end_line), file, or whole_change.
21	- If nothing is actionable, use an empty array: "comments":[].
22	- This line is required even where other instructions say to output nothing else.`
23	
24	// maxTrailJSONLines bounds the backward scan for a pretty-printed JSON block.
25	const maxTrailJSONLines = 200
26	
27	// TrailComment is one finding in the trail JSON contract.
28	type TrailComment struct {
29		Severity   string        `json:"severity"`
30		Confidence *float64      `json:"confidence,omitempty"`
31		Body       string        `json:"body"`
32		Location   TrailLocation `json:"location"`
33	}
34	
35	// TrailLocation anchors a TrailComment to the change.
36	type TrailLocation struct {
37		Granularity  string `json:"granularity"`
38		FilePath     string `json:"file_path,omitempty"`
39		StartLine    int    `json:"start_line,omitempty"`
40		EndLine      int    `json:"end_line,omitempty"`
41		SelectedText string `json:"selected_text,omitempty"`
42	}
43	
44	// TrailReport is what a trail-mode run posts: structured comments from
45	// reviews that honored the JSON contract, and the prose, with any contract
46	// line removed, of those that did not. At least one of the two is set.
47	type TrailReport struct {
48		Comments []TrailComment
49		Prose    string
50	}
51	
52	// trailReportFor decides what a trail-mode run posts. It returns post=false
53	// only when the JSON contract reports no findings and nothing in the prose
54	// contradicts that; every malformed or contradictory case posts, so a
55	// misbehaving model costs an extra finding rather than a lost one. A posted
56	// report is empty only when the output had nothing readable. When a judge
57	// ran, its verdict decides: it is asked to drop unsupported claims.
58	func trailReportFor(summary reviewtypes.RunSummary, aggregateOutput string) (TrailReport, bool) {
59		if verdict := strings.TrimSpace(aggregateOutput); verdict != "" {
60			prose, comments, ok := splitTrailJSON(verdict)
61			if !contractCoversProse(prose, comments, ok) {
62				if prose == "" {
63					// A JSON-only reply without a summary has no prose of its own.
64					prose = combinedReviewNarratives(usableAgentRuns(summary))
65				}
66				return TrailReport{Prose: prose}, true
67			}
68			return TrailReport{Comments: comments}, len(comments) > 0
69		}
70		var merged []TrailComment
71		var unstructured []reviewtypes.AgentRun
72		for _, run := range usableAgentRuns(summary) {
73			prose, comments, ok := splitTrailJSON(reportText(run.Buffer))
74			if !contractCoversProse(prose, comments, ok) {
75				unstructured = append(unstructured, run)
76				continue
77			}
78			merged = append(merged, comments...)
79		}
80		report := TrailReport{Comments: merged, Prose: combinedReviewNarratives(unstructured)}
81		return report, len(merged) > 0 || len(unstructured) > 0
82	}
83	
84	// contractCoversProse reports whether a valid contract can be posted in place
85	// of its prose: the prose reports no finding the comments leave out. That
86	// means no more severity-marked findings than comments, and no file:line the
87	// comments do not cover; locations catch a finding however the prose is laid
88	// out. The prose normally repeats every comment, so it is posted instead of,
89	// not alongside, an incomplete contract.
90	func contractCoversProse(prose string, comments []TrailComment, ok bool) bool {
91		if !ok {
92			return false
93		}
94		if len(comments) == 0 {
95			return !proseReportsFindings(prose)
96		}
97		return markedFindingCount(prose) <= len(comments) && locationsCovered(prose, comments)
98	}
99	
100	// LocationPattern matches a file:line reference such as "retry.go:42".
101	var LocationPattern = regexp.MustCompile("(?:^|[\\s(`])([A-Za-z0-9_./-]+\\.[A-Za-z0-9_+-]+):(\\d+)")
102	
103	// locationsCovered reports whether every file:line the prose cites falls in a
104	// comment's location on the same file or is cited in a comment's body.
105	func locationsCovered(prose string, comments []TrailComment) bool {
106		for _, match := range LocationPattern.FindAllStringSubmatch(prose, -1) {
107			path := match[1]
108			line, err := strconv.Atoi(match[2])
109			if err != nil {
110				continue
111			}
112			if !locationCovered(path, line, comments) {
113				return false
114			}
115		}
116		return true
117	}
118	
119	func locationCovered(path string, line int, comments []TrailComment) bool {
120		ref := path + ":" + strconv.Itoa(line)
121		for _, comment := range comments {
122			if strings.Contains(comment.Body, ref) {
123				return true
124			}
125			loc := comment.Location
126			if !samePath(loc.FilePath, path) || loc.StartLine <= 0 {
127				continue
128			}
129			if line >= loc.StartLine && line <= max(loc.EndLine, loc.StartLine) {
130				return true
131			}
132		}
133		return false
134	}
135	
136	// samePath reports whether two paths name the same file, allowing one to be
137	// a shorter suffix of the other ("retry.go" and "internal/retry.go").
138	func samePath(a, b string) bool {
139		a, b = strings.TrimPrefix(a, "./"), strings.TrimPrefix(b, "./")
140		if a == "" || b == "" {
141			return false
142		}
143		return a == b || strings.HasSuffix(a, "/"+b) || strings.HasSuffix(b, "/"+a)
144	}
145	
146	// markedFindingCount counts the findings prose reports with a severity, the
147	// finding shape the output format asks for: lines at any indentation, list
148	// items included, that open with a severity marker, and findings without one
149	// under a severity heading.
150	func markedFindingCount(prose string) int {
151		count := 0
152		for _, line := range strings.Split(prose, "\n") {
153			if _, _, ok := severityGroupLabel(line); ok {
154				continue
155			}
156			trimmed := strings.TrimSpace(line)
157			if item, ok := ListItemText(trimmed); ok {
158				trimmed = item
159			}
160			if StartsWithSeverityMarker(trimmed) {
161				count++
162			}
163		}
164		for _, finding := range SplitProseFindings(prose) {
165			if finding.Severity != "" && !StartsWithSeverityMarker(finding.Text) {
166				count++
167			}
168		}
169		return count
170	}
171	
172	// reportText returns a reviewer's report: the last stretch of text between
173	// tool calls that ends with a valid contract line, or "" if none does. It is
174	// found by the contract line rather than by position, so a tool call after
175	// the report does not hide it, and earlier exploration narration, whose
176	// bullets ("I'll check:\n- retry.go") are not findings, is left out. A tool
177	// call inside a message, where the next text continues it as a delta, is not
178	// a boundary. A stretch holding only the contract line also takes the latest
179	// text before it that reports findings by more than bullets, so a report
180	// written before the final tool calls is still checked against the line while
181	// a bulleted file list is not.
182	func reportText(buf []reviewtypes.Event) string {
183		end := len(buf)
184		for i := len(buf) - 1; i >= -1; i-- {
185			if i >= 0 && !isTextBoundary(buf, i) {
186				continue
187			}
188			text := joinAssistantText(buf[i+1 : end])
189			prose, payload, found := splitTrailJSONPayload(text)
190			if _, ok := decodeTrailComments(payload["comments"]); !found || !ok {
191				end = i
192				continue
193			}
194			if prose == "" && i >= 0 {
195				if before := lastMarkedReportBefore(buf, i); before != "" {
196					return before + "\n\n" + text
197				}
198			}
199			return text
200		}
201		return ""
202	}
203	
204	// lastMarkedReportBefore returns the latest stretch of text before buf[end]
205	// that reports findings by more than bullets, or "" if none does.
206	func lastMarkedReportBefore(buf []reviewtypes.Event, end int) string {
207		for i := end - 1; i >= -1; i-- {
208			if i >= 0 && !isTextBoundary(buf, i) {
209				continue
210			}
211			if text := joinAssistantText(buf[i+1 : end]); proseReportsMarkedFindings(text) {
212				return text
213			}
214			end = i
215		}
216		return ""
217	}
218	
219	// isTextBoundary reports whether buf[i] is a tool call that separates two
220	// stretches of text rather than interrupting a message.
221	func isTextBoundary(buf []reviewtypes.Event, i int) bool {
222		_, ok := buf[i].(reviewtypes.ToolCall)
223		return ok && !continuesMessage(buf[i+1:])
224	}
225	
226	// continuesMessage reports whether the first text in buf continues the
227	// message before it.
228	func continuesMessage(buf []reviewtypes.Event) bool {
229		for _, ev := range buf {
230			if at, ok := ev.(reviewtypes.AssistantText); ok {
231				return at.Delta
232			}
233		}
234		return false
235	}
236	
237	// splitTrailJSON separates a trailing contract-shaped JSON object (one line,
238	// a fenced block, or a pretty-printed block, with a "summary" or "comments"
239	// key) from the prose before it, so a malformed contract is never posted as
240	// finding text. Other trailing JSON, such as a config snippet quoted as
241	// evidence, stays in the prose. A JSON-only reply contributes its summary as
242	// the prose instead. ok reports a valid contract: a "comments" array.
243	// Entries without a body are dropped.
244	func splitTrailJSON(text string) (prose string, comments []TrailComment, ok bool) {
245		prose, payload, found := splitTrailJSONPayload(text)
246		if !found {
247			return prose, nil, false
248		}
249		if prose == "" {
250			var summary string
251			if json.Unmarshal(payload["summary"], &summary) == nil {
252				prose = strings.TrimSpace(summary)
253			}
254		}
255		comments, ok = decodeTrailComments(payload["comments"])
256		return prose, comments, ok
257	}
258	
259	// splitTrailJSONPayload finds a trailing contract-shaped JSON object and
260	// returns the prose before it and its decoded keys. found is false, with
261	// the whole text as prose, when there is none.
262	func splitTrailJSONPayload(text string) (prose string, payload map[string]json.RawMessage, found bool) {
263		text = strings.TrimSpace(text)
264		lines := strings.Split(text, "\n")
265		end := len(lines)
266		fenced := end > 1 && strings.TrimSpace(lines[end-1]) == "```"
267		if fenced {
268			end--
269		}
270		for start := end - 1; start >= 0 && start >= end-maxTrailJSONLines; start-- {
271			if !strings.HasPrefix(strings.TrimSpace(lines[start]), "{") {
272				continue
273			}
274			payload = nil
275			if err := json.Unmarshal([]byte(strings.Join(lines[start:end], "\n")), &payload); err != nil {
276				continue
277			}
278			_, hasSummary := payload["summary"]
279			_, hasComments := payload["comments"]
280			if !hasSummary && !hasComments {
281				break
282			}
283			proseEnd := start
284			if fenced && proseEnd > 0 && strings.HasPrefix(strings.TrimSpace(lines[proseEnd-1]), "```") {
285				proseEnd--
286			}
287			return strings.TrimSpace(strings.Join(lines[:proseEnd], "\n")), payload, true
288		}
289		return text, nil, false
290	}
291	
292	func decodeTrailComments(raw json.RawMessage) ([]TrailComment, bool) {
293		if !strings.HasPrefix(strings.TrimSpace(string(raw)), "[") {
294			return nil, false
295		}
296		var decoded []TrailComment
297		if err := json.Unmarshal(raw, &decoded); err != nil {
298			return nil, false
299		}
300		comments := []TrailComment{}
301		for _, comment := range decoded {
302			if strings.TrimSpace(comment.Body) != "" {
303				comments = append(comments, comment)
304			}
305		}
306		return comments, true
307	}
308	
309	// stripTrailJSON removes a valid trailing contract line for display. Only a
310	// run that asked for the line has one; elsewhere a trailing JSON block is the
311	// reviewer's own text and stays.
312	func stripTrailJSON(text string, trailFindingsJSON bool) string {
313		if !trailFindingsJSON {
314			return text
315		}
316		if prose, _, ok := splitTrailJSON(text); ok {
317			return prose
318		}
319		return text
320	}
321	
322	// proseReportsFindings reports whether prose contradicts an empty comments
323	// array: a list item at any indentation, or a finding proseReportsMarkedFindings
324	// recognizes. These are the shapes the output format asks for, so a clean
325	// review has none of them. A list item that only says a section is empty
326	// ("- None") is not a finding.
327	func proseReportsFindings(prose string) bool {
328		for _, line := range strings.Split(prose, "\n") {
329			if item, ok := ListItemText(strings.TrimSpace(line)); ok && !isNoFindingsText(item) {
330				return true
331			}
332		}
333		return proseReportsMarkedFindings(prose)
334	}
335	
336	// proseReportsMarkedFindings reports whether prose reports findings by more
337	// than bullets: a severity marker or feedback label such as "Nits:" at any
338	// indentation, a finding under a severity heading, or a verdict, labeled or
339	// not, that itself says there is feedback. A bulleted file list in
340	// exploration narration has none of these.
341	func proseReportsMarkedFindings(prose string) bool {
342		for _, line := range strings.Split(prose, "\n") {
343			if _, _, ok := severityGroupLabel(line); ok {
344				continue
345			}
346			trimmed := strings.TrimSpace(line)
347			if item, ok := ListItemText(trimmed); ok {
348				trimmed = item
349			}
350			lower := strings.ToLower(trimMarkdownEmphasis(trimmed))
351			if after, found := strings.CutPrefix(lower, "verdict"); found {
352				lower = trimMarkdownEmphasis(strings.TrimLeft(after, ":-—– "))
353			}
354			if StartsWithSeverityMarker(lower) {
355				return true
356			}
357			for _, prefix := range []string{
358				"request changes", "request_changes", "changes requested", "approve with nits",
359				"needs changes", "needs work", "changes needed",
360				"nits:", "issues:", "concerns:", "suggestions:", "findings:", "problems:", "blocking:",
361			} {
362				if strings.HasPrefix(lower, prefix) {
363					return true
364				}
365			}
366		}
367		return markedFindingCount(prose) > 0
368	}
369	
370	func trimMarkdownEmphasis(s string) string {
371		return strings.TrimLeft(s, "#>*_` ")
372	}
373	
374	// StartsWithSeverityMarker reports whether line, after leading Markdown
375	// emphasis, opens with a severity tag: bracketed ("[high]"), delimited
376	// ("high —", "p2:"), closed by emphasis ("**High** ..."), or alone (a "### High"
377	// heading). A word that merely starts with a marker ("Highlights") is not one.
378	func StartsWithSeverityMarker(line string) bool {
379		return LeadingSeverity(line) != ""
380	}
381	
382	// LeadingSeverity returns the severity tag line opens with, in lower case, as
383	// StartsWithSeverityMarker recognizes it, or "" if there is none.
384	func LeadingSeverity(line string) string {
385		lower := strings.ToLower(trimMarkdownEmphasis(strings.TrimSpace(line)))
386		for _, marker := range severityMarkers {
387			if strings.HasPrefix(lower, "["+marker+"]") {
388				return marker
389			}
390			rest, found := strings.CutPrefix(lower, marker)
391			if !found {
392				continue
393			}
394			if strings.TrimSpace(rest) == "" {
395				return marker
396			}
397			for _, suffix := range []string{" —", " –", " -", ":", "*", "_"} {
398				if strings.HasPrefix(rest, suffix) {
399					return marker
400				}
401			}
402		}
403		return ""
404	}
405	
406	var severityMarkers = []string{"critical", "high", "medium", "low", "p0", "p1", "p2", "p3", "nit"}
407	
408	// severityGroupLabel reports whether line, unindented, labels a group of
409	// findings by severity and returns the label in lower case and the heading
410	// level (0 for a label that is not a "#" heading): a line holding only a
411	// severity ("### High", "**Low:**", "Nits:"), or a heading whose first word is
412	// one followed by a delimiter or a qualifier ("### High severity",
413	// "## P1 — must fix"). "## High Level Summary" is not one.
414	func severityGroupLabel(line string) (string, int, bool) {
415		level := headingLevel(line)
416		if label, ok := severityLabel(line); ok {
417			return label, level, true
418		}
419		if level == 0 {
420			return "", 0, false
421		}
422		words := strings.Fields(strings.TrimLeft(line, "#"))
423		if len(words) == 0 {
424			return "", 0, false
425		}
426		label, ok := severityLabel(words[0])
427		if !ok {
428			return "", 0, false
429		}
430		if len(words) == 1 || strings.HasSuffix(words[0], ":") || isSeverityQualifier(words[1]) {
431			return label, level, true
432		}
433		return "", 0, false
434	}
435	
436	func isSeverityQualifier(word string) bool {
437		word = strings.ToLower(strings.Trim(word, "*_`:"))
438		if strings.HasPrefix(word, "(") {
439			return true
440		}
441		switch word {
442		case "—", "–", "-", "severity", "priority", "issues", "findings", "risk":
443			return true
444		}
445		return false
446	}
447	
448	// detailLabels are labels that add detail to or sum up the finding before
449	// them rather than starting one.
450	var detailLabels = map[string]bool{
451		"fix": true, "impact": true, "problem": true, "issue": true, "why": true,
452		"evidence": true, "suggestion": true, "recommendation": true, "note": true,
453		"location": true, "file": true, "files": true, "details": true, "description": true,
454		"context": true, "cause": true, "root cause": true, "rationale": true, "example": true,
455		"repro": true, "reproduction": true, "severity": true, "priority": true, "risk": true,
456		"confidence": true, "summary": true, "verdict": true, "overall": true, "conclusion": true,
457	}
458	
459	// opensWithDetailLabel reports whether text opens with a detail label
460	// ("**Fix:** ...", "Impact: ...", "**Summary**: ...", "Recommended fix:") or
461	// is one alone.
462	func opensWithDetailLabel(text string) bool {
463		label, _, _ := strings.Cut(strings.TrimLeft(text, "#*_` "), ":")
464		label = strings.ToLower(strings.Trim(label, "*_` "))
465		return detailLabels[label] || strings.HasSuffix(label, " fix")
466	}
467	
468	// isLabelTitle reports whether a sub-heading title only names a category or
469	// file ("Correctness", "`retry.go`") rather than stating a finding.
470	func isLabelTitle(title string) bool {
471		if item, ok := ListItemText(title); ok {
472			title = item
473		}
474		words := 0
475		for i, part := range strings.Split(title, "`") {
476			if i%2 == 0 {
477				words += len(strings.Fields(strings.Trim(part, "*_:()")))
478			}
479		}
480		return words <= 1
481	}
482	
483	// headingLevel returns the level of an unindented Markdown "#" heading, or 0.
484	func headingLevel(line string) int {
485		level := len(line) - len(strings.TrimLeft(line, "#"))
486		if level == 0 || !strings.HasPrefix(line[level:], " ") {
487			return 0
488		}
489		return level
490	}
491	
492	// severityLabel reports whether line, unindented, holds only a severity
493	// label ("### High", "**Low:**", "Nits:") and returns it in lower case.
494	func severityLabel(line string) (string, bool) {
495		if line != strings.TrimLeft(line, " \t") {
496			return "", false
497		}
498		label := strings.TrimLeft(strings.TrimSpace(line), "#>*_`[ ")
499		label = strings.ToLower(strings.TrimRight(label, ":*_`] "))
500		for _, marker := range severityMarkers {
501			if label == marker || label == marker+"s" {
502				return label, true
503			}
504		}
505		return "", false
506	}
507	
508	var noFindingsPattern = regexp.MustCompile(`^(none|nothing|n/?a|no (\S+ ){0,3}(issues|findings|concerns|problems))( (found|identified|noted|to report))?$`)
509	
510	// isNoFindingsText reports whether text only says a section is empty
511	// ("None.", "No high-severity issues."), as reviews often write under a
512	// severity heading with nothing in it.
513	func isNoFindingsText(text string) bool {
514		return noFindingsPattern.MatchString(strings.ToLower(strings.Trim(text, "*_`.!:() \t")))
515	}
516	
517	// ProseFinding is one top-level finding in prose. Severity is the label of
518	// the severity heading it sits under ("high", "p2"), or "" outside one.
519	type ProseFinding struct {
520		Text     string
521		Severity string
522	}
523	
524	// SplitProseFindings splits prose into its top-level findings: list items and
525	// lines that open with a severity marker, each with the lines that continue
526	// it. A severity group label ("### High", "**Low:**", "## P1 — must fix")
527	// groups the findings below it rather than being one. In a group, text that is
528	// not a list item is a finding too, and a deeper heading or a bold paragraph
529	// starts a new one. List items under a sub-heading that states a finding are
530	// its details; under one that only names a category or file ("Correctness",
531	// "`retry.go`") they are findings and the title is dropped. A line opening
532	// with a detail label such as "Fix:" or "**Summary:**" continues the finding
533	// before it. A group ends at a
534	// heading at its level or above, a "Summary"-style sub-heading, or a
535	// placeholder such as "None." directly under its label, so a closing summary
536	// is not a finding; a placeholder under a sub-heading drops only that
537	// sub-heading. Trail posting counts findings with this and the bridge posts
538	// them, so both agree on what a finding is.
539	func SplitProseFindings(prose string) []ProseFinding {
540		var findings []ProseFinding
541		var current strings.Builder
542		group, groupLevel := "", 0
543		afterBlank := false
544		// headingOnly marks that the current finding holds only a sub-heading's
545		// title so far; headingDetails marks that the list items under that
546		// title are its details.
547		headingOnly, headingDetails := false, false
548		flush := func() {
549			text := strings.TrimSpace(current.String())
550			current.Reset()
551			headingOnly, headingDetails = false, false
552			if text != "" {
553				findings = append(findings, ProseFinding{Text: text, Severity: group})
554			}
555		}
556		appendLine := func(line string) {
557			if current.Len() > 0 {
558				current.WriteByte('\n')
559			}
560			current.WriteString(line)
561			if strings.TrimSpace(line) != "" {
562				headingOnly = false
563			}
564		}
565		for _, line := range strings.Split(strings.TrimSpace(prose), "\n") {
566			blank := strings.TrimSpace(line) == ""
567			paragraphStart := afterBlank
568			afterBlank = blank
569			if label, level, ok := severityGroupLabel(line); ok {
570				flush()
571				group, groupLevel = label, level
572				continue
573			}
574			if level := headingLevel(line); level > 0 && group != "" {
575				flush()
576				title := strings.TrimSpace(strings.TrimLeft(line, "#"))
577				if groupLevel > 0 && level > groupLevel && !opensWithDetailLabel(title) {
578					current.WriteString(title)
579					headingOnly = true
580				} else {
581					group = ""
582				}
583				continue
584			}
585			item, isItem := topLevelListItemText(line)
586			if headingOnly && ((isItem && isNoFindingsText(item)) || (!isItem && isNoFindingsText(line))) {
587				current.Reset()
588				headingOnly = false
589				continue
590			}
591			if current.Len() > 0 && opensWithDetailLabel(strings.TrimSpace(line)) {
592				appendLine(line)
593				continue
594			}
595			if isItem && headingOnly {
596				if isLabelTitle(strings.TrimSpace(current.String())) {
597					current.Reset()
598					headingOnly = false
599				} else {
600					headingDetails = true
601				}
602			}
603			if isItem && current.Len() > 0 && (headingDetails || opensWithDetailLabel(item)) {
604				appendLine(line)
605				continue
606			}
607			if isItem {
608				flush()
609				if isNoFindingsText(item) {
610					group = ""
611				} else {
612					current.WriteString(item)
613				}
614				continue
615			}
616			if line == strings.TrimLeft(line, " \t") && StartsWithSeverityMarker(line) {
617				flush()
618				current.WriteString(strings.TrimSpace(line))
619				continue
620			}
621			if group != "" && paragraphStart && strings.HasPrefix(line, "**") {
622				flush()
623			}
624			if current.Len() == 0 {
625				if group == "" || blank {
626					continue
627				}
628				if isNoFindingsText(line) {
629					group = ""
630					continue
631				}
632			}
633			appendLine(line)
634		}
635		flush()
636		return findings
637	}
638	
639	func topLevelListItemText(line string) (string, bool) {
640		if line != strings.TrimLeft(line, " \t") {
641			return "", false
642		}
643		item, ok := ListItemText(strings.TrimSpace(line))
644		return item, ok && item != ""
645	}
646	
647	// ListItemText returns the text of a Markdown list item ("- ", "* ", "+ ",
648	// "• ", "1. ", "1) ") and whether trimmed, a line without surrounding space,
649	// is one.
650	func ListItemText(trimmed string) (string, bool) {
651		for _, bullet := range []string{"- ", "* ", "+ ", "• "} {
652			if item, found := strings.CutPrefix(trimmed, bullet); found {
653				return strings.TrimSpace(item), true
654			}
655		}
656		digits := len(trimmed) - len(strings.TrimLeft(trimmed, "0123456789"))
657		if digits == 0 {
658			return "", false
659		}
660		for _, delim := range []string{". ", ") "} {
661			if item, found := strings.CutPrefix(trimmed[digits:], delim); found {
662				return strings.TrimSpace(item), true
663			}
664		}
665		return "", false
666	}
